CREATE TABLE IF NOT EXISTS authors(id TEXT PRIMARY KEY,author_id TEXT UNIQUE NOT NULL,name TEXT,status TEXT,first_seen TEXT,last_seen TEXT);
CREATE TABLE IF NOT EXISTS author_bank_accounts(id TEXT PRIMARY KEY,author_id TEXT,account_number TEXT,ifsc TEXT,bank_name TEXT,verification_status TEXT,successful_payment_count INTEGER DEFAULT 0,first_successful_payment TEXT,last_successful_payment TEXT,is_current INTEGER DEFAULT 0,source_month TEXT);
CREATE TABLE IF NOT EXISTS content_items(id TEXT PRIMARY KEY,book_id TEXT,show_id TEXT,author_id TEXT,content_type TEXT,content_subtype TEXT,language TEXT,parent_book_id TEXT,parent_show_id TEXT,relationship_type TEXT);
CREATE TABLE IF NOT EXISTS import_batches(id TEXT PRIMARY KEY,filename TEXT,payment_period TEXT,checksum TEXT UNIQUE,status TEXT,imported_at TEXT,total_rows INTEGER DEFAULT 0,payment_event_rows INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS raw_import_rows(id TEXT PRIMARY KEY,batch_id TEXT,source_sheet TEXT,source_row INTEGER,sheet_kind TEXT,payload TEXT);
CREATE TABLE IF NOT EXISTS payment_transactions(id TEXT PRIMARY KEY,author_id TEXT,book_id TEXT,show_id TEXT,payment_type TEXT,amount_before_tax NUMERIC,amount_after_tax NUMERIC,currency TEXT,status TEXT,utr TEXT,transaction_date TEXT,payout_id TEXT,original_status TEXT,source_file TEXT,source_sheet TEXT,source_row INTEGER,payment_period TEXT,content_type TEXT,ledger_state TEXT DEFAULT 'OPEN',account_number TEXT,ifsc TEXT,bank_name TEXT);
CREATE TABLE IF NOT EXISTS earnings(id TEXT PRIMARY KEY,payment_period TEXT,reward_type TEXT,author_id TEXT,book_id TEXT,show_id TEXT,content_type TEXT,pay_flag TEXT,exclusion_reason TEXT,gross NUMERIC,tds NUMERIC,net NUMERIC,product_rs NUMERIC,source_file TEXT,source_sheet TEXT,source_row INTEGER);
CREATE TABLE IF NOT EXISTS payout_batches(id TEXT PRIMARY KEY,payment_period TEXT,status TEXT,created_at TEXT,frozen_at TEXT,notes TEXT);
CREATE TABLE IF NOT EXISTS payout_lines(id TEXT PRIMARY KEY,batch_id TEXT,payment_period TEXT,author_id TEXT,gross_incentive NUMERIC DEFAULT 0,gross_revenue_share NUMERIC DEFAULT 0,other_earnings NUMERIC DEFAULT 0,gross_payable NUMERIC DEFAULT 0,marketing NUMERIC DEFAULT 0,platform NUMERIC DEFAULT 0,cop NUMERIC DEFAULT 0,flat_deduction NUMERIC DEFAULT 0,recovery NUMERIC DEFAULT 0,adjustment NUMERIC DEFAULT 0,tds NUMERIC DEFAULT 0,net_payable NUMERIC DEFAULT 0,qc_status TEXT,freeze_status TEXT);
CREATE TABLE IF NOT EXISTS payout_line_earnings(id TEXT PRIMARY KEY,payout_line_id TEXT,earning_id TEXT);
CREATE TABLE IF NOT EXISTS qc_results(id TEXT PRIMARY KEY,period TEXT,entity_type TEXT,entity_id TEXT,rule_id TEXT,severity TEXT,message TEXT,detected_value TEXT,expected_value TEXT,status TEXT);
CREATE TABLE IF NOT EXISTS exception_cases(id TEXT PRIMARY KEY,period TEXT,category TEXT,entity_type TEXT,entity_id TEXT,severity TEXT,status TEXT,reason TEXT,resolution TEXT);
CREATE TABLE IF NOT EXISTS reconciliation_events(id TEXT PRIMARY KEY,payment_transaction_id TEXT,match_type TEXT,finance_status TEXT,ledger_state TEXT,notes TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS rule_configs(id TEXT PRIMARY KEY,rule_key TEXT,scope_type TEXT,scope_value TEXT,value_numeric NUMERIC,value_text TEXT,effective_from TEXT,effective_to TEXT,is_active INTEGER DEFAULT 1,approved_by TEXT,reason TEXT);
